"""Tests for tasks_api.queries — TaskQuery validation, apply_query filtering/sorting/pagination."""

from __future__ import annotations

from datetime import datetime, timezone, timedelta

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskQuery, TaskQueryError, TaskPage, apply_query


NOW = datetime(2026, 7, 1, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="t", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, tags=None, created_at=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, created_at=created_at or NOW, tags=tags or [],
    )


# ── TaskQuery validation ─────────────────────────────────────────────

class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0

    def test_invalid_sort(self):
        with pytest.raises(TaskQueryError, match="sort must be"):
            TaskQuery(sort="nope")

    def test_limit_zero(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(limit=0)

    def test_limit_over_100(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(limit=101)

    def test_negative_offset(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(offset=-1)

    def test_tag_normalized(self):
        q = TaskQuery(tag="  HELLO  ")
        assert q.tag == "hello"

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_stripped(self):
        q = TaskQuery(search="  buy  ")
        assert q.search == "buy"


# ── TaskPage ─────────────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_task(1)], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false(self):
        page = TaskPage(items=[_task(1)], total=1, limit=10, offset=0)
        assert page.has_more is False


# ── apply_query filtering ────────────────────────────────────────────

class TestApplyQueryFiltering:
    @pytest.fixture
    def tasks(self):
        return [
            _task(1, "Buy milk", status=TaskStatus.PENDING, priority=TaskPriority.HIGH,
                  tags=[Tag("shopping")]),
            _task(2, "Write report", status=TaskStatus.DONE, priority=TaskPriority.LOW),
            _task(3, "Fix bug", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
                  due_at=datetime(2020, 1, 1, tzinfo=timezone.utc), tags=[Tag("dev")]),
            _task(4, "Buy groceries", status=TaskStatus.PENDING, priority=TaskPriority.LOW,
                  due_at=datetime(2030, 1, 1, tzinfo=timezone.utc), tags=[Tag("shopping")]),
        ]

    def test_no_filter(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 4

    def test_filter_status_pending(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert page.total == 3

    def test_filter_status_done(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="shopping"), NOW)
        assert page.total == 2

    def test_filter_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="buy"), NOW)
        assert page.total == 2

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].id == 3

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        assert page.total == 3

    def test_combined_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, tag="shopping"), NOW)
        assert page.total == 2


# ── apply_query sorting ──────────────────────────────────────────────

class TestApplyQuerySorting:
    def test_sort_by_title_asc(self):
        tasks = [_task(1, "Banana"), _task(2, "Apple"), _task(3, "Cherry")]
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Apple", "Banana", "Cherry"]

    def test_sort_by_title_desc(self):
        tasks = [_task(1, "Banana"), _task(2, "Apple")]
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        assert [t.title for t in page.items] == ["Banana", "Apple"]

    def test_sort_by_priority(self):
        tasks = [
            _task(1, "low", priority=TaskPriority.LOW),
            _task(2, "high", priority=TaskPriority.HIGH),
            _task(3, "med", priority=TaskPriority.MEDIUM),
        ]
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        assert [t.title for t in page.items] == ["high", "med", "low"]

    def test_sort_by_due_at(self):
        tasks = [
            _task(1, "no due"),
            _task(2, "soon", due_at=datetime(2026, 8, 1, tzinfo=timezone.utc)),
            _task(3, "later", due_at=datetime(2027, 1, 1, tzinfo=timezone.utc)),
        ]
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        assert page.items[0].title == "soon"
        assert page.items[-1].title == "no due"

    def test_sort_by_created_at(self):
        tasks = [
            _task(1, "newer", created_at=datetime(2026, 7, 2, tzinfo=timezone.utc)),
            _task(2, "older", created_at=datetime(2026, 6, 1, tzinfo=timezone.utc)),
        ]
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert page.items[0].title == "older"


# ── apply_query pagination ───────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def many_tasks(self):
        return [_task(i, f"task-{i}") for i in range(1, 11)]

    def test_limit(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 10
        assert page.has_more is True

    def test_offset(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(limit=5, offset=8), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_total(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(offset=100), NOW)
        assert len(page.items) == 0
        assert page.total == 10

